UPDATE EMPLOYEE 
SET total_score = #{totalScore}, final_grade = #{finalGrade} 
WHERE id = #{id}

UPDATE EMPLOYEE 
SET department_id = #{departmentId}, name = #{name}, email = #{email}, position = #{position}, is_leader = #{isLeader}, role = #{role}
WHERE id = #{id}

UPDATE EMPLOYEE 
SET failed_attempts = failed_attempts + 1
WHERE login_id = #{loginId}

UPDATE EMPLOYEE
SET is_locked = 1
WHERE login_id = #{loginId}

UPDATE EMPLOYEE
SET failed_attempts = 0
WHERE login_id = #{loginId}

UPDATE EMPLOYEE
SET failed_attempts = 0, is_locked = 0, password = '{noop}password'
WHERE id = #{id}

UPDATE EMPLOYEE
SET password = #{password}
WHERE id = #{id}
